DROP TABLE IF EXISTS rescate_colbosque_20260928;
CREATE TABLE rescate_colbosque_20260928 (id INT UNSIGNED PRIMARY KEY, nota_hoy INT NULL, nota_20sep INT NOT NULL);
SELECT COUNT(*) AS reservadas FROM rescate_colbosque_20260928;
START TRANSACTION;
UPDATE notas n JOIN rescate_colbosque_20260928 r ON r.id = n.id SET n.nota = r.nota_20sep
 WHERE n.deleted_at IS NULL AND n.nota <=> r.nota_hoy AND n.updated_by IS NULL AND n.created_at <=> n.updated_at;
COMMIT;
